-- ════════════════════════════════════════════════════════════════
--  Campora — core schema (portable: PostgreSQL + H2 in PostgreSQL mode)
--
--  Conventions on every table
--    id           UUID primary key (generated by the application)
--    created_at / updated_at / created_by / updated_by   audit trail
--    deleted      soft-delete flag (rows are never physically removed)
--    version      optimistic-locking counter
-- ════════════════════════════════════════════════════════════════

-- ── Identity ────────────────────────────────────────────────────
CREATE TABLE app_role (
    id           UUID PRIMARY KEY,
    name         VARCHAR(20)  NOT NULL,
    description  VARCHAR(200),
    created_at   TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at   TIMESTAMP WITH TIME ZONE NOT NULL,
    created_by   VARCHAR(64),
    updated_by   VARCHAR(64),
    deleted      BOOLEAN NOT NULL DEFAULT FALSE,
    version      BIGINT  NOT NULL DEFAULT 0,
    CONSTRAINT uk_role_name UNIQUE (name)
);

CREATE TABLE app_user (
    id                  UUID PRIMARY KEY,
    role_id             UUID REFERENCES app_role (id),
    first_name          VARCHAR(60)  NOT NULL,
    last_name           VARCHAR(60)  NOT NULL,
    mobile_number       VARCHAR(15)  NOT NULL,
    password_hash       VARCHAR(100) NOT NULL,
    status              VARCHAR(24)  NOT NULL,
    mobile_verified_at  TIMESTAMP WITH TIME ZONE,
    created_at          TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at          TIMESTAMP WITH TIME ZONE NOT NULL,
    created_by          VARCHAR(64),
    updated_by          VARCHAR(64),
    deleted             BOOLEAN NOT NULL DEFAULT FALSE,
    version             BIGINT  NOT NULL DEFAULT 0,
    CONSTRAINT uk_user_mobile UNIQUE (mobile_number)
);

-- ── Campus reference data ───────────────────────────────────────
CREATE TABLE department (
    id           UUID PRIMARY KEY,
    code         VARCHAR(16)  NOT NULL,
    name         VARCHAR(120) NOT NULL,
    active       BOOLEAN NOT NULL DEFAULT TRUE,
    created_at   TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at   TIMESTAMP WITH TIME ZONE NOT NULL,
    created_by   VARCHAR(64),
    updated_by   VARCHAR(64),
    deleted      BOOLEAN NOT NULL DEFAULT FALSE,
    version      BIGINT  NOT NULL DEFAULT 0,
    CONSTRAINT uk_department_code UNIQUE (code)
);

-- A destination is any named stop: a point on campus or a place in the city.
CREATE TABLE destination (
    id           UUID PRIMARY KEY,
    name         VARCHAR(120) NOT NULL,
    area         VARCHAR(120),
    type         VARCHAR(20)  NOT NULL,
    active       BOOLEAN NOT NULL DEFAULT TRUE,
    sort_order   INTEGER NOT NULL DEFAULT 100,
    created_at   TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at   TIMESTAMP WITH TIME ZONE NOT NULL,
    created_by   VARCHAR(64),
    updated_by   VARCHAR(64),
    deleted      BOOLEAN NOT NULL DEFAULT FALSE,
    version      BIGINT  NOT NULL DEFAULT 0,
    CONSTRAINT uk_destination_name UNIQUE (name)
);

-- ── Profiles (one per user, by role) ────────────────────────────
CREATE TABLE student_profile (
    id             UUID PRIMARY KEY,
    user_id        UUID NOT NULL REFERENCES app_user (id),
    department_id  UUID NOT NULL REFERENCES department (id),
    enrollment_no  VARCHAR(32) NOT NULL,
    semester       INTEGER NOT NULL,
    created_at     TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at     TIMESTAMP WITH TIME ZONE NOT NULL,
    created_by     VARCHAR(64),
    updated_by     VARCHAR(64),
    deleted        BOOLEAN NOT NULL DEFAULT FALSE,
    version        BIGINT  NOT NULL DEFAULT 0,
    CONSTRAINT uk_student_user UNIQUE (user_id),
    CONSTRAINT uk_student_enrollment UNIQUE (enrollment_no),
    CONSTRAINT ck_student_semester CHECK (semester BETWEEN 1 AND 12)
);

CREATE TABLE driver_profile (
    id              UUID PRIMARY KEY,
    user_id         UUID NOT NULL REFERENCES app_user (id),
    vehicle_type    VARCHAR(20) NOT NULL,
    vehicle_number  VARCHAR(20) NOT NULL,
    seat_capacity   INTEGER NOT NULL,
    native_area     VARCHAR(120),
    availability    VARCHAR(12) NOT NULL,
    verified        BOOLEAN NOT NULL DEFAULT FALSE,
    created_at      TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at      TIMESTAMP WITH TIME ZONE NOT NULL,
    created_by      VARCHAR(64),
    updated_by      VARCHAR(64),
    deleted         BOOLEAN NOT NULL DEFAULT FALSE,
    version         BIGINT  NOT NULL DEFAULT 0,
    CONSTRAINT uk_driver_user UNIQUE (user_id),
    CONSTRAINT uk_driver_vehicle UNIQUE (vehicle_number),
    CONSTRAINT ck_driver_capacity CHECK (seat_capacity BETWEEN 1 AND 12)
);

-- ── Mobility: demand and responses ──────────────────────────────
CREATE TABLE travel_request (
    id              UUID PRIMARY KEY,
    student_id      UUID NOT NULL REFERENCES student_profile (id),
    pickup_id       UUID NOT NULL REFERENCES destination (id),
    destination_id  UUID NOT NULL REFERENCES destination (id),
    request_type    VARCHAR(16) NOT NULL,
    seats_required  INTEGER NOT NULL,
    status          VARCHAR(16) NOT NULL,
    expires_at      TIMESTAMP WITH TIME ZONE NOT NULL,
    created_at      TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at      TIMESTAMP WITH TIME ZONE NOT NULL,
    created_by      VARCHAR(64),
    updated_by      VARCHAR(64),
    deleted         BOOLEAN NOT NULL DEFAULT FALSE,
    version         BIGINT  NOT NULL DEFAULT 0,
    CONSTRAINT ck_request_seats CHECK (seats_required BETWEEN 1 AND 6),
    CONSTRAINT ck_request_route CHECK (pickup_id <> destination_id)
);

CREATE TABLE companion_ride (
    id               UUID PRIMARY KEY,
    host_id          UUID NOT NULL REFERENCES student_profile (id),
    pickup_id        UUID NOT NULL REFERENCES destination (id),
    destination_id   UUID NOT NULL REFERENCES destination (id),
    departure_time   TIMESTAMP WITH TIME ZONE NOT NULL,
    total_seats      INTEGER NOT NULL,
    available_seats  INTEGER NOT NULL,
    status           VARCHAR(16) NOT NULL,
    note             VARCHAR(200),
    created_at       TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at       TIMESTAMP WITH TIME ZONE NOT NULL,
    created_by       VARCHAR(64),
    updated_by       VARCHAR(64),
    deleted          BOOLEAN NOT NULL DEFAULT FALSE,
    version          BIGINT  NOT NULL DEFAULT 0,
    CONSTRAINT ck_ride_seats CHECK (available_seats >= 0 AND available_seats <= total_seats),
    CONSTRAINT ck_ride_route CHECK (pickup_id <> destination_id)
);

CREATE TABLE trip (
    id                 UUID PRIMARY KEY,
    trip_type          VARCHAR(16) NOT NULL,
    driver_id          UUID REFERENCES driver_profile (id),
    companion_ride_id  UUID REFERENCES companion_ride (id),
    pickup_id          UUID NOT NULL REFERENCES destination (id),
    destination_id     UUID NOT NULL REFERENCES destination (id),
    seats_reserved     INTEGER NOT NULL,
    status             VARCHAR(16) NOT NULL,
    start_time         TIMESTAMP WITH TIME ZONE,
    end_time           TIMESTAMP WITH TIME ZONE,
    created_at         TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at         TIMESTAMP WITH TIME ZONE NOT NULL,
    created_by         VARCHAR(64),
    updated_by         VARCHAR(64),
    deleted            BOOLEAN NOT NULL DEFAULT FALSE,
    version            BIGINT  NOT NULL DEFAULT 0,
    CONSTRAINT uk_trip_companion_ride UNIQUE (companion_ride_id)
);

CREATE TABLE driver_response (
    id              UUID PRIMARY KEY,
    request_id      UUID NOT NULL REFERENCES travel_request (id),
    driver_id       UUID NOT NULL REFERENCES driver_profile (id),
    trip_id         UUID NOT NULL REFERENCES trip (id),
    seats_reserved  INTEGER NOT NULL,
    status          VARCHAR(16) NOT NULL,
    created_at      TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at      TIMESTAMP WITH TIME ZONE NOT NULL,
    created_by      VARCHAR(64),
    updated_by      VARCHAR(64),
    deleted         BOOLEAN NOT NULL DEFAULT FALSE,
    version         BIGINT  NOT NULL DEFAULT 0
);

CREATE TABLE companion_ride_member (
    id                 UUID PRIMARY KEY,
    ride_id            UUID NOT NULL REFERENCES companion_ride (id),
    student_id         UUID NOT NULL REFERENCES student_profile (id),
    travel_request_id  UUID REFERENCES travel_request (id),
    seats              INTEGER NOT NULL,
    status             VARCHAR(16) NOT NULL,
    created_at         TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at         TIMESTAMP WITH TIME ZONE NOT NULL,
    created_by         VARCHAR(64),
    updated_by         VARCHAR(64),
    deleted            BOOLEAN NOT NULL DEFAULT FALSE,
    version            BIGINT  NOT NULL DEFAULT 0
);

CREATE TABLE destination_request (
    id              UUID PRIMARY KEY,
    student_id      UUID NOT NULL REFERENCES student_profile (id),
    proposed_name   VARCHAR(120) NOT NULL,
    area            VARCHAR(120),
    reason          VARCHAR(300),
    status          VARCHAR(16) NOT NULL,
    review_note     VARCHAR(300),
    reviewed_at     TIMESTAMP WITH TIME ZONE,
    created_at      TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at      TIMESTAMP WITH TIME ZONE NOT NULL,
    created_by      VARCHAR(64),
    updated_by      VARCHAR(64),
    deleted         BOOLEAN NOT NULL DEFAULT FALSE,
    version         BIGINT  NOT NULL DEFAULT 0
);

-- ── Indexes for the hot paths ───────────────────────────────────
-- Hotspot aggregation + seat reservation scan open demand per route.
CREATE INDEX ix_request_cluster  ON travel_request (status, pickup_id, destination_id, created_at);
CREATE INDEX ix_request_student  ON travel_request (student_id, status);
CREATE INDEX ix_request_expiry   ON travel_request (status, expires_at);
CREATE INDEX ix_response_request ON driver_response (request_id);
CREATE INDEX ix_response_trip    ON driver_response (trip_id);
CREATE INDEX ix_trip_driver      ON trip (driver_id, status);
CREATE INDEX ix_ride_status      ON companion_ride (status, departure_time);
CREATE INDEX ix_ride_host        ON companion_ride (host_id, status);
CREATE INDEX ix_member_ride      ON companion_ride_member (ride_id, status);
CREATE INDEX ix_member_student   ON companion_ride_member (student_id, status);
CREATE INDEX ix_destreq_status   ON destination_request (status, created_at);
CREATE INDEX ix_user_role        ON app_user (role_id);
